begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)
select ('a9000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','staff-'||i||'@example.test',now(),now(),now() from generate_series(1,7)i;
insert into public.organizations(id,name,slug,status) values('b9000000-0000-4000-8000-000000000001','Equipe A','staff-a','active'),('b9000000-0000-4000-8000-000000000002','Equipe B','staff-b','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('c9000000-0000-4000-8000-000000000001','b9000000-0000-4000-8000-000000000001','Sede equipe A','staff-a','headquarters'),('c9000000-0000-4000-8000-000000000002','b9000000-0000-4000-8000-000000000002','Sede equipe B','staff-b','headquarters');
insert into public.organization_memberships(organization_id,user_id,role,status,default_unit_id)
select 'b9000000-0000-4000-8000-000000000001',('a9000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,(case i when 1 then 'owner' when 2 then 'admin' when 3 then 'pastor' else 'secretary' end)::public.membership_role,'active','c9000000-0000-4000-8000-000000000001' from generate_series(1,4)i;
select ok(not has_table_privilege('authenticated','public.staff_invitations','INSERT'),'cliente não fabrica convite diretamente');
select ok(not has_table_privilege('authenticated','public.staff_invitations','UPDATE'),'cliente não troca email/token/papel');
select ok(not has_function_privilege('anon','public.accept_staff_invitation(uuid)','EXECUTE'),'visitante não aceita convite');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.staff_directory('b9000000-0000-4000-8000-000000000001')$$,'42501',null,'secretaria não lista identidades da equipe');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.create_staff_invitation('b9000000-0000-4000-8000-000000000001','c9000000-0000-4000-8000-000000000001','staff-5@example.test','Convidada','secretary')$$,'0A000',null,'convites desativados para administrador');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(jsonb_array_length(public.staff_directory('b9000000-0000-4000-8000-000000000001')->'users'),4,'gestor vê somente equipe do ministério');
select throws_ok($$select public.staff_directory('b9000000-0000-4000-8000-000000000002')$$,'42501',null,'diretório de outro ministério é negado');
select throws_ok($$select public.create_staff_invitation('b9000000-0000-4000-8000-000000000001','c9000000-0000-4000-8000-000000000001','staff-5@example.test','Convidada','secretary')$$,'0A000',null,'convites desativados para o dono');
reset role;
-- Convites antigos ainda pendentes (anteriores à ficha de usuários) continuam protegidos no aceite.
insert into public.staff_invitations(organization_id,unit_id,email,full_name,role,token,status,created_by,expires_at) values('b9000000-0000-4000-8000-000000000001','c9000000-0000-4000-8000-000000000001','staff-5@example.test','Convidada','secretary',gen_random_uuid(),'pending','a9000000-0000-4000-8000-000000000001',now()+interval '7 days');
set local role authenticated;
reset role;
select set_config('vinha.staff_token',(select token::text from public.staff_invitations where email='staff-5@example.test'),true);
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000007","role":"authenticated"}',true);
select throws_ok($$select public.accept_staff_invitation(current_setting('vinha.staff_token')::uuid)$$,'42501',null,'outra conta não aceita convite');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select is((public.accept_staff_invitation(current_setting('vinha.staff_token')::uuid)->>'ok')::boolean,true,'conta confirmada aceita convite');
select is((public.accept_staff_invitation(current_setting('vinha.staff_token')::uuid)->>'alreadyAccepted')::boolean,true,'convite aceito retoma acesso ativo');
reset role;
select is((select count(*) from public.organization_memberships where user_id='a9000000-0000-4000-8000-000000000005'),1::bigint,'repetição não duplica participação');
select is((select access_level::text from public.membership_unit_access g join public.organization_memberships m on m.id=g.membership_id where m.user_id='a9000000-0000-4000-8000-000000000005'),'manage','secretaria recebe somente unidade prevista');
update public.organization_memberships set status='suspended' where user_id='a9000000-0000-4000-8000-000000000005';
set local role authenticated;
select throws_ok($$select public.accept_staff_invitation(current_setting('vinha.staff_token')::uuid)$$,'42501',null,'convite aceito não reativa suspensão');
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
reset role;
insert into public.staff_invitations(organization_id,unit_id,email,full_name,role,token,status,created_by,expires_at) values('b9000000-0000-4000-8000-000000000001','c9000000-0000-4000-8000-000000000001','staff-6@example.test','Outro convidado','pastor',gen_random_uuid(),'pending','a9000000-0000-4000-8000-000000000002',now()+interval '7 days');
set local role authenticated;
reset role;
select set_config('vinha.staff_token2',(select token::text from public.staff_invitations where email='staff-6@example.test'),true);
update public.organization_memberships set role='secretary' where user_id='a9000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a9000000-0000-4000-8000-000000000006","role":"authenticated"}',true);
select throws_ok($$select public.accept_staff_invitation(current_setting('vinha.staff_token2')::uuid)$$,'42501',null,'emissor rebaixado perde concessão pendente');
reset role;
select is((select count(*) from public.organization_memberships where user_id='a9000000-0000-4000-8000-000000000006'),0::bigint,'recusa não cria participação parcial');
select * from finish();
rollback;
